const models=modelData.map(([id,title,category,source,allowedFormats,defaultFields,icon,contextType=''])=>({id,title,category,source,allowedFormats,defaultFields,icon,contextType}));
const modelById=id=>models.find(model=>model.id===id);
const ensureSettings=()=>state.settings.documentTemplates||(state.settings.documentTemplates={});
const ensureGenerated=()=>state.generatedDocuments||(state.generatedDocuments=[]);
const isoDay=value=>{const d=value?new Date(value):new Date();return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10)};
const currentMonthRange=()=>{const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),1);return{dateFrom:isoDay(start),dateTo:isoDay(now)}};
const datedSources=new Set(['sales','employeeSales','sellerSummary','cash','stock','clientLedger','cashClosing','closings','saleItems']);
const defaultFooterFor=model=>model.id==='client-debt'?'Demostrativo de deuda emitido por el sistema. Valores sujetos a los movimientos registrados en la cuenta del cliente.':model.id==='sale-receipt'?'Comprobante comercial de venta. No sustituye una factura fiscal homologada por el SIN.':model.id==='zona-franca-invoice'?'Modelo comercial. La validez fiscal requiere integración homologada con el SIN.':'Documento generado por FLORALIS PDV & ERP';
const configFor=model=>({title:model.title,format:model.allowedFormats[0],fontSize:'large',...currentMonthRange(),showLogo:true,showBusiness:true,showPeriod:datedSources.has(model.source),showSignature:false,footer:defaultFooterFor(model),fields:model.defaultFields,...ensureSettings()[model.id],...Object.fromEntries(Object.entries(studio.context||{}).filter(([key])=>['dateFrom','dateTo'].includes(key))),style:'official',accent:'#111111'});
const fieldLabel=(source,key)=>fieldSets[source]?.find(([id])=>id===key)?.[1]||key;
const safeDate=value=>{try{return date(value)}catch{return'—'}};
const safeTime=value=>{try{return time(value)}catch{return'—'}};
const parseBoundary=(value,end=false)=>{if(!value)return end?Infinity:-Infinity;return new Date(`${value}T${end?'23:59:59.999':'00:00:00'}`).getTime()};
const inRange=(value,config={})=>{const current=new Date(value).getTime();return Number.isFinite(current)&&current>=parseBoundary(config.dateFrom)&&current<=parseBoundary(config.dateTo,true)};
const stripInternal=row=>Object.fromEntries(Object.entries(row).filter(([key])=>!key.startsWith('_')));
const salesInRange=config=>(state.sales||[]).filter(s=>(s.type||'Venta')==='Venta'&&inRange(s.date,config));
const saleFor=(context=studio.context)=>{const key=context?.saleId;return key?(state.sales||[]).find(s=>s.id===key||s.uuid===key||s.clientSaleId===key):null};
const employeeFor=(context=studio.context)=>{const key=context?.employeeId,name=context?.employeeName;return key||name?(state.employees||[]).find(e=>(key&&e.id===key)||(name&&e.name===name)):null};
const clientFor=(context=studio.context)=>{const key=context?.clientId,name=context?.clientName;return key||name?(state.clients||[]).find(c=>(key&&c.id===key)||(name&&c.name===name)):null};
function sellerRows(config){const sales=salesInRange(config),total=sum(sales,'total'),groups=new Map();sales.forEach(s=>{const key=s.employeeId||s.employee||'Sin vendedor',current=groups.get(key)||{name:s.employee||'Sin vendedor',employeeId:s.employeeId,sales:0,items:0,total:0};current.sales++;current.items+=Number(s.items||0);current.total+=Number(s.total||0);groups.set(key,current)});return[...groups.values()].map(row=>{const employee=(state.employees||[]).find(e=>e.id===row.employeeId||e.name===row.name);return{...row,role:employee?.role||'Vendedor'}}).sort((a,b)=>b.total-a.total).map((row,index)=>({rank:`${index+1}º`,name:row.name,role:row.role,sales:row.sales,items:row.items,total:money(row.total),ticket:money(row.sales?row.total/row.sales:0),share:`${total?Math.round(row.total/total*100):0}%`,highlight:index===0?'Mayor facturación':'—'}))}
function cashClosingMovements(context,config){const closing=context.closingId?(state.closings||[]).find(c=>c.id===context.closingId):null;if(closing){const start=new Date(closing.openedAt||closing.date).getTime(),end=new Date(closing.date).getTime();return(state.cash||[]).filter(m=>{const when=new Date(m.date).getTime();return when>=start&&when<=end}).sort((a,b)=>new Date(a.date)-new Date(b.date))}return(state.cash||[]).filter(m=>inRange(m.date,config)).sort((a,b)=>new Date(a.date)-new Date(b.date))}
function cashClosingRows(context,config){let balance=0;return cashClosingMovements(context,config).map(m=>{balance+=m.type==='in'?Number(m.amount||0):-Number(m.amount||0);const parts=String(m.description||'').split('—');return{_date:m.date,date:safeDate(m.date),time:safeTime(m.date),type:m.type==='in'?'Entrada':'Salida',description:parts[0]?.trim()||'—',employee:m.employee||'—',payment:parts[1]?.trim()||'—',income:m.type==='in'?money(m.amount):'—',expense:m.type==='out'?money(m.amount):'—',balance:money(balance)}})}
function clientLedgerRows(context,config){const client=clientFor(context);if(!client)return[];const ledger=[...(client.ledger||[])],sales=(state.sales||[]).filter(s=>(s.clientId&&s.clientId===client.id)||s.client===client.name),linked=new Set();sales.forEach(s=>ledger.forEach((entry,index)=>{if((entry.saleId&&s.uuid&&entry.saleId===s.uuid)||(s.id&&String(entry.description||'').includes(s.id)))linked.add(index)}));const ledgerImpact=ledger.reduce((n,entry)=>n+(entry.type==='credit'?Number(entry.amount||0):-Number(entry.amount||0)),0);let balance=Number(client.balance||0)-ledgerImpact;const events=[...sales.map(s=>({date:s.date,type:'Venta',description:`Venta ${s.id}`,reference:s.id,payment:s.payment||'—',amount:Number(s.total||0),impact:s.payment==='Cuenta cliente'?-Number(s.total||0):0})),...ledger.filter((_,index)=>!linked.has(index)).map(entry=>({date:entry.date,type:entry.type==='credit'?'Crédito / pago':'Débito',description:entry.description||'Movimiento de cuenta',reference:entry.reference||'Cuenta corriente',payment:entry.paymentMethod||'—',amount:Number(entry.amount||0),impact:entry.type==='credit'?Number(entry.amount||0):-Number(entry.amount||0)}))].sort((a,b)=>new Date(a.date)-new Date(b.date));return events.map(event=>{balance+=event.impact;return{_date:event.date,_impact:event.impact,date:safeDate(event.date),time:safeTime(event.date),type:event.type,description:event.description,reference:event.reference,payment:event.payment,amount:money(event.amount),debit:event.impact<0?money(Math.abs(event.impact)):'—',credit:event.impact>0?money(event.impact):'—',balance:money(balance)}}).filter(row=>inRange(row._date,config))}
function clientDebtRows(context){let accumulated=0;return clientLedgerRows(context,{}).filter(row=>Number(row._impact)<0).map(row=>{accumulated+=Math.abs(Number(row._impact)||0);return{...row,balance:money(accumulated)}})}
function sourceRows(source,context=studio.context,config=currentMonthRange()){
 const selectedSale=saleFor(context),selectedEmployee=employeeFor(context);
 if(source==='saleItems'){const items=selectedSale?.receiptItems||selectedSale?.itemsDetail||[];return items.map((item,index)=>{const quantity=Number(item.quantity||item.qty||0),unitPrice=Number(item.unitPrice??item.price??0),basePrice=Number(item.basePrice??unitPrice),lineDiscount=Math.max(0,(basePrice-unitPrice)*quantity),product=(state.products||[]).find(entry=>entry.id===(item.productId||item.product_id||item.id));return{code:item.code||item.productCode||product?.code||item.product_id||String(index).padStart(6,'0'),product:item.name||item.product||item.description||product?.name||'Producto',quantity:quantity.toLocaleString(locale()),unit:item.unit||product?.unit||'Unidad',unitPrice:money(unitPrice),discount:money(lineDiscount),total:money(item.total??quantity*unitPrice)}})}
 if(source==='clientDebt')return clientDebtRows(context);
 if(source==='sales')return(state.sales||[]).filter(s=>inRange(s.date,config)).map(s=>({number:s.id,date:safeDate(s.date),time:safeTime(s.date),client:s.client||'Consumidor final',seller:s.employee||'—',payment:s.payment||'—',kind:s.type||'Venta',items:s.items||0,subtotal:money(s.subtotal??s.total),discount:money(s.discountTotal||0),total:money(s.total)}));
 if(source==='employeeSales')return(state.sales||[]).filter(s=>inRange(s.date,config)&&((selectedEmployee?.id&&s.employeeId===selectedEmployee.id)||(selectedEmployee?.name&&s.employee===selectedEmployee.name))).map(s=>({number:s.id,date:safeDate(s.date),time:safeTime(s.date),client:s.client||'Consumidor final',payment:s.payment||'—',items:s.items||0,total:money(s.total)}));
 if(source==='products')return(state.products||[]).map(p=>({code:p.code||p.ean||'—',name:p.name,category:p.category||'—',unit:p.unit||'Unidad',stock:Number(p.stock||0).toLocaleString(locale()),minimum:Number(p.minStock||0).toLocaleString(locale()),cost:money(p.cost),price:money(p.price),wholesale:money(p.wholesale),supplier:p.supplier||'—',profit:`${p.cost?Math.round((p.price-p.cost)/p.cost*100):0}%`}));
 if(source==='clients')return(state.clients||[]).map(c=>({code:c.code||'—',name:c.name,type:c.type||'—',document:c.document||'—',phone:c.phone||'—',city:c.city||'—',balance:money(c.balance),purchases:c.purchases||0,total:money(c.total)}));
 if(source==='cash')return(state.cash||[]).filter(m=>inRange(m.date,config)).map(m=>({date:safeDate(m.date),time:safeTime(m.date),type:m.type==='in'?'Entrada':'Salida',description:m.description,employee:m.employee||'—',income:m.type==='in'?money(m.amount):'—',expense:m.type==='out'?money(m.amount):'—',amount:money(m.amount),client:m.client||'—'}));
 if(source==='stock')return(state.stockMovements||[]).filter(m=>inRange(m.date,config)).map(m=>{const p=(state.products||[]).find(x=>x.id===m.productId);return{date:safeDate(m.date),time:safeTime(m.date),product:p?.name||'Producto eliminado',code:p?.code||'—',type:m.type==='in'?'Entrada':m.type==='out'?'Salida':'Corrección',quantity:Number(m.amount||0).toLocaleString(locale()),reason:m.reason||'—',employee:m.employee||'—'}});
 if(source==='employees')return(state.employees||[]).map(e=>({name:e.name,role:e.role||'—',sales:e.sales||0,total:money(e.total),ticket:money(e.ticket),commission:money(Number(e.total||0)*.01),goal:`${e.goal||0}%`}));
 if(source==='sellerSummary')return sellerRows(config);
 if(source==='cashClosing')return cashClosingRows(context,config);
 if(source==='clientLedger')return clientLedgerRows(context,config).map(stripInternal);
 if(source==='closings')return(state.closings||[]).filter(c=>inRange(c.date,config)).map(c=>({date:safeDate(c.date),opened:safeTime(c.openedAt),closed:safeTime(c.date),employee:c.employee||'—',income:money(c.entries),expense:money(c.exits),total:money(c.total),reason:c.reason||'—'}));
 return[];
}
function summaryFor(model,rows){const label={saleItems:'ítems de la venta',sales:'registros de venta',employeeSales:'ventas del funcionario',products:'productos',clients:'clientes',cash:'movimientos',stock:'movimientos',employees:'funcionarios',sellerSummary:'vendedores',cashClosing:'movimientos de caja',clientDebt:'movimientos con deuda',clientLedger:'movimientos del cliente',closings:'cierres',payables:'cuentas',purchases:'compras',fiscal:'documentos'}[model.source]||'registros';return`${rows.length} ${label}`}
function documentKpis(model,rows,context,config){
 if(model.source==='sellerSummary'){const sales=salesInRange(config),total=sum(sales,'total');return[['Ventas',sales.length],['Facturado',money(total)],['Ticket promedio',money(sales.length?total/sales.length:0)],['Mejor vendedor',rows[0]?.name||'—']]}
 if(model.source==='cashClosing'){const movements=cashClosingMovements(context,config),ins=sum(movements.filter(m=>m.type==='in'),'amount'),outs=sum(movements.filter(m=>m.type==='out'),'amount');return[['Movimientos',rows.length],['Entradas',money(ins)],['Salidas',money(outs)],['Saldo esperado',money(ins-outs)]]}
 if(model.source==='clientDebt'){const client=clientFor(context),balance=Number(client?.balance||0);return[['Cliente',client?.name||'Seleccione un cliente'],['Situación',balance<0?'Con deuda':balance>0?'Con crédito':'Cuenta al día'],['Compras',client?.purchases||0],['Saldo actual',money(Math.abs(balance))]]}
 if(model.source==='clientLedger'){const client=clientFor(context);return[['Cliente',client?.name||'Seleccione un cliente'],['Compras',client?.purchases||0],['Total comprado',money(client?.total||0)],['Saldo actual',money(client?.balance||0)]]}
 if(model.source==='employeeSales'){const employee=employeeFor(context),sales=(state.sales||[]).filter(s=>inRange(s.date,config)&&((employee?.id&&s.employeeId===employee.id)||s.employee===employee?.name)),total=sum(sales,'total');return[['Funcionario',employee?.name||'—'],['Ventas',sales.length],['Facturado',money(total)],['Ticket promedio',money(sales.length?total/sales.length:0)]]}
 if(model.source==='saleItems'){const sale=saleFor(context);return[['Cliente',sale?.client||'Consumidor final'],['Pago',sale?.payment||'—'],['Ítems',sale?.items||rows.length],['Total',money(sale?.total||0)]]}
 return[];
}
function periodText(config){if(!config.dateFrom&&!config.dateTo)return'Todo el historial';if(config.dateFrom===config.dateTo)return config.dateFrom?safeDate(`${config.dateFrom}T12:00:00`):'Todo el historial';return`${config.dateFrom?safeDate(`${config.dateFrom}T12:00:00`):'Inicio'} — ${config.dateTo?safeDate(`${config.dateTo}T12:00:00`):'Hoy'}`}
function documentMeta(model,context){const sale=saleFor(context),generated=context.generatedRecord;if(sale)return{label:'VENTA',number:sale.id||'V000000',date:safeDate(sale.date),time:safeTime(sale.date)};if(generated)return{label:'DOCUMENTO',number:generated.documentNumber||'D000000',date:safeDate(generated.createdAt),time:safeTime(generated.createdAt)};return{label:'DOCUMENTO',number:'Vista previa',date:safeDate(new Date()),time:safeTime(new Date())}}
function contextLine(model,context){const client=clientFor(context),employee=employeeFor(context),sale=saleFor(context);if(sale)return`${sale.client||'Consumidor final'} · ${sale.payment||'—'}`;if(client)return`${client.name} · ${client.document||client.code||'Sin documento'} · ${client.phone||'Sin teléfono'}`;if(employee)return`${employee.name} · ${employee.role||'Funcionario'}`;if(model.source==='cashClosing')return'Detalle de entradas, salidas y saldo acumulado';return''}
const referenceValue=value=>value==null||value===''?'—':String(value);
const referenceClass=(model,config,name)=>`document-sheet reference-document reference-${name} format-${esc(config.format)} style-${esc(config.style)} font-${esc(config.fontSize)}`;
function referenceLogo(config,business){if(!config.showLogo)return'';return business.logo?`<img src="${esc(business.logo)}" alt="Logotipo de ${esc(business.businessName||'la empresa')}">`:`<span class="reference-logo-placeholder">${esc((business.businessName||'G')[0])}</span>`}
function saleClient(sale){return(state.clients||[]).find(client=>client.id===sale?.clientId||client.name===sale?.client)||null}
function saleItemsWithBlanks(sale,minRows=7){const rows=sourceRows('saleItems',{saleId:sale?.uuid||sale?.id},{}),blanks=Array.from({length:Math.max(0,minRows-rows.length)},()=>null);return[...rows,...blanks]}
function referenceArticle(model,config,name,content){return`<article class="${referenceClass(model,config,name)}" style="--doc-accent:${esc(config.accent)}" data-reference-template="${esc(name)}">${content}</article>`}
function closingRange(context,config){const closing=context.closingId?(state.closings||[]).find(item=>item.id===context.closingId):null;return{closing,start:closing?new Date(closing.openedAt||closing.date).getTime():parseBoundary(config.dateFrom),end:closing?new Date(closing.date).getTime():parseBoundary(config.dateTo,true)}}
function referenceCashSales(context,config){const bounds=closingRange(context,config);return(state.sales||[]).filter(sale=>(sale.type||'Venta')==='Venta'&&new Date(sale.date).getTime()>=bounds.start&&new Date(sale.date).getTime()<=bounds.end)}
function cashPaymentSummary(sales,movements){const methods=['Efectivo','PIX','QR','Transferencia'],manual=movements.filter(movement=>!/^Venta\b/i.test(String(movement.description||''))),sangria=sum(manual.filter(movement=>movement.type==='out'),'amount'),supplement=sum(manual.filter(movement=>movement.type==='in'&&!/^Pago\b/i.test(String(movement.description||''))),'amount');return methods.map(method=>{const sold=sum(sales.filter(sale=>sale.payment===method),'total'),cashMethod=method==='Efectivo';return{method,sales:sold,returns:0,sangria:cashMethod?sangria:0,supplement:cashMethod?supplement:0,total:sold-(cashMethod?sangria:0)+(cashMethod?supplement:0)}})}
function cashTransactionRows(sales,movements){const saleRows=sales.map(sale=>({date:sale.date,number:sale.id,type:'Venta',description:sale.client||'Consumidor final',discount:Number(sale.discountTotal||0),total:Number(sale.total||0),payment:sale.payment||'—',notes:sale.notes||sale.delivery||'—'})),movementRows=movements.filter(movement=>!/^Venta\b/i.test(String(movement.description||''))).map(movement=>({date:movement.date,number:movement.id,type:movement.type==='in'?'Entrada':'Salida',description:movement.description||'Movimiento de caja',discount:0,total:Number(movement.amount||0),payment:'Efectivo',notes:movement.employee||'—'}));return[...saleRows,...movementRows].sort((a,b)=>new Date(a.date)-new Date(b.date))}
